import { generateDeck, parseBoardCode, type BoardDescription } from './board.ts';

export const SELECTION_KINDS = ['closed', 'one', 'mismatch'] as const;
export type SelectionKind = (typeof SELECTION_KINDS)[number];

export interface ClosedSelection { readonly kind: 'closed' }
export interface OneSelection { readonly kind: 'one'; readonly index: number }
export interface MismatchSelection {
  readonly kind: 'mismatch';
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}
export type Selection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({ kind: 'closed' });
export const GAME_LIMITS = Object.freeze({
  mismatchMs: 800,
  maxMoves: 999_999,
  maxElapsedMs: 359_999_999,
});

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (board === null) return null;
  return Object.freeze({
    board,
    deck: generateDeck(board),
    matched: Object.freeze([]),
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

export function matchedPairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function formatTime(elapsedMs: number): string {
  const totalSeconds = Math.floor(elapsedMs / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = String(totalSeconds % 60).padStart(2, '0');
  return `${minutes}:${seconds}`;
}
export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export const MAX_SEED = 2_147_483_646;
const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const PARK_MILLER_RANGE = PARK_MILLER_MODULUS - 1;

export interface BoardDescription {
  readonly boardCode: string;
  readonly size: (typeof BOARD_SIZES)[number];
  readonly seed: number;
}

export function isBoardSize(value: unknown): value is (typeof BOARD_SIZES)[number] {
  return typeof value === 'number' && BOARD_SIZES.some((size) => size === value);
}

export function parseBoardCode(value: unknown): BoardDescription | null {
  if (typeof value !== 'string') return null;
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(value);
  if (match === null) return null;
  const rawSize = Number(match[1]);
  const seed = Number(match[2]);
  if (!isBoardSize(rawSize) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ boardCode: value, size: rawSize, seed });
}

function draw(state: { value: number }, bound: number): number {
  const limit = Math.floor(PARK_MILLER_RANGE / bound) * bound;
  while (true) {
    state.value = (state.value * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
    const candidate = state.value - 1;
    if (candidate < limit) return candidate % bound;
  }
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const cards = board.size * board.size;
  const deck = Array.from({ length: cards }, (_unused, index) => Math.floor(index / 2));
  const generator = { value: board.seed };
  for (let index = cards - 1; index > 0; index -= 1) {
    const other = draw(generator, index + 1);
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace === undefined || otherFace === undefined) continue;
    deck[index] = otherFace;
    deck[other] = currentFace;
  }
  return Object.freeze(deck);
}

import { CLOSED_SELECTION, GAME_LIMITS, isWon, type GameState, type MismatchSelection } from './state.ts';

function isCardIndex(state: GameState, index: number): boolean {
  return Number.isSafeInteger(index) && index >= 0 && index < state.deck.length;
}

function hasMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

function addMove(moves: number): number {
  return Math.min(GAME_LIMITS.maxMoves, moves + 1);
}

export function activateCard(state: GameState, index: number): GameState {
  if (!isCardIndex(state, index) || isWon(state) || hasMatched(state, index)) return state;
  switch (state.selection.kind) {
    case 'closed':
      return Object.freeze({ ...state, started: true, selection: Object.freeze({ kind: 'one', index }) });
    case 'one': {
      if (state.selection.index === index) return state;
      const moves = addMove(state.moves);
      const firstFace = state.deck[state.selection.index];
      const secondFace = state.deck[index];
      if (firstFace === secondFace) {
        const matched = Object.freeze([...state.matched, state.selection.index, index]);
        return Object.freeze({ ...state, matched, moves, selection: CLOSED_SELECTION });
      }
      const selection: MismatchSelection = Object.freeze({
        kind: 'mismatch', first: state.selection.index, second: index, remainingMs: GAME_LIMITS.mismatchMs,
      });
      return Object.freeze({ ...state, moves, selection });
    }
    case 'mismatch':
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(GAME_LIMITS.maxElapsedMs, state.elapsedMs + milliseconds);
  switch (state.selection.kind) {
    case 'closed':
    case 'one':
      return Object.freeze({ ...state, elapsedMs });
    case 'mismatch':
      if (milliseconds >= state.selection.remainingMs) {
        return Object.freeze({ ...state, elapsedMs, selection: CLOSED_SELECTION });
      }
      return Object.freeze({
        ...state,
        elapsedMs,
        selection: Object.freeze({ ...state.selection, remainingMs: state.selection.remainingMs - milliseconds }),
      });
  }
}
import { createGame, GAME_LIMITS, isWon, type GameState, type Selection } from './state.ts';
import { hasExactKeys, isIndex, isRecord, isSafeCount, parseJson } from './formatValidation.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65_536;

export function encodeSnapshot(state: GameState): string {
  let selection: unknown;
  switch (state.selection.kind) {
    case 'closed':
      selection = { kind: 'closed' };
      break;
    case 'one':
      selection = { kind: 'one', index: state.selection.index };
      break;
    case 'mismatch':
      selection = {
        kind: 'mismatch',
        first: state.selection.first,
        second: state.selection.second,
        remainingMs: Math.max(1, Math.ceil(state.selection.remainingMs)),
      };
      break;
  }
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: state.board.boardCode,
    matched: state.matched,
    selection,
    moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started,
  });
}

function parseSelection(value: unknown, state: GameState, matched: ReadonlySet<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null;
  switch (value.kind) {
    case 'closed':
      return hasExactKeys(value, ['kind']) ? Object.freeze({ kind: 'closed' }) : null;
    case 'one':
      if (!hasExactKeys(value, ['kind', 'index']) || !isIndex(value.index, state.deck.length)) return null;
      return matched.has(value.index) ? null : Object.freeze({ kind: 'one', index: value.index });
    case 'mismatch':
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
      if (!isIndex(value.first, state.deck.length) || !isIndex(value.second, state.deck.length)) return null;
      if (value.first === value.second || matched.has(value.first) || matched.has(value.second)) return null;
      if (state.deck[value.first] === state.deck[value.second]) return null;
      if (!isSafeCount(value.remainingMs) || value.remainingMs < 1 || value.remainingMs > GAME_LIMITS.mismatchMs) return null;
      return Object.freeze({ kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs });
    default:
      return null;
  }
}

function hasCompletePairs(state: GameState, matched: readonly number[]): boolean {
  const positions = new Set(matched);
  for (const index of matched) {
    const face = state.deck[index];
    if (face === undefined) return false;
    const first = state.deck.indexOf(face);
    const second = state.deck.lastIndexOf(face);
    if (!positions.has(first) || !positions.has(second)) return false;
  }
  return true;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseJson(text, SNAPSHOT_BYTE_LIMIT);
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'])) return null;
  if (value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  const base = createGame(value.boardCode);
  if (base === null || !Array.isArray(value.matched)) return null;
  if (!isSafeCount(value.moves) || value.moves > GAME_LIMITS.maxMoves) return null;
  if (!isSafeCount(value.elapsedMs) || value.elapsedMs > GAME_LIMITS.maxElapsedMs || typeof value.started !== 'boolean') return null;
  const matched: number[] = [];
  for (const index of value.matched) {
    if (!isIndex(index, base.deck.length) || matched.includes(index)) return null;
    matched.push(index);
  }
  if (matched.length % 2 !== 0 || !hasCompletePairs(base, matched)) return null;
  const matchedSet = new Set(matched);
  const selection = parseSelection(value.selection, base, matchedSet);
  if (selection === null || (isWon({ ...base, matched }) && selection.kind !== 'closed')) return null;
  const pairCount = matched.length / 2;
  const minimumMoves = pairCount + (selection.kind === 'mismatch' ? 1 : 0);
  if (value.moves < minimumMoves) return null;
  if (!value.started) {
    if (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed') return null;
  } else if (value.moves === 0 && selection.kind !== 'one') {
    return null;
  }
  return Object.freeze({ ...base, matched: Object.freeze(matched), selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started });
}
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function hasExactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === expected.length && expected.every((key) => Object.hasOwn(value, key));
}

export function isSafeCount(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function isIndex(value: unknown, length: number): value is number {
  return isSafeCount(value) && value < length;
}

export function isJsonWithinBytes(text: string, limit: number): boolean {
  return new TextEncoder().encode(text).byteLength <= limit;
}

export function parseJson(text: string, limit: number): unknown | null {
  if (!isJsonWithinBytes(text, limit)) return null;
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return null;
  }
}

