import { describe, expect, it } from 'vitest';
import { BOARD_SIZES, generateDeck, parseBoardCode } from './board.ts';
import { createGame } from './state.ts';

describe('board codes and deals', () => {
  it('reproduces the literal version 1 seed vector', () => {
    const game = createGame('np1-4-1');
    expect(game?.deck).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
  });

  it('accepts only supported sizes and canonical bounded decimal seeds', () => {
    expect(parseBoardCode('np1-16-2147483646')?.seed).toBe(2_147_483_646);
    for (const code of ['np1-4-0', 'np1-04-1', 'np1-5-1', 'np1-4-01', 'np1-4-2147483647', 'NP1-4-1', ' np1-4-1', 'np1-4-1 ', 'np1-4-1\n']) {
      expect(parseBoardCode(code), code).toBeNull();
    }
  });

  it('creates exactly two of every face at each supported size', () => {
    for (const size of BOARD_SIZES) {
      const board = parseBoardCode(`np1-${size}-77`);
      expect(board).not.toBeNull();
      if (board === null) continue;
      const deck = generateDeck(board);
      expect(deck).toHaveLength(size * size);
      for (let face = 0; face < deck.length / 2; face += 1) {
        expect(deck.filter((value) => value === face)).toHaveLength(2);
      }
    }
  });
});
import { describe, expect, it } from 'vitest';
import { advanceGame, activateCard } from './transitions.ts';
import { createGame, formatTime, isWon, matchedPairCount } from './state.ts';

describe('card transitions and logical time', () => {
  it('ignores repeated, matched, invalid, and mismatch-blocked activations', () => {
    const initial = createGame('np1-4-1');
    if (initial === null) throw new Error('Literal fixture must be valid');
    const one = activateCard(initial, 0);
    expect(activateCard(one, 0)).toBe(one);
    const mismatch = activateCard(one, 1);
    expect(mismatch.selection.kind).toBe('mismatch');
    expect(mismatch.moves).toBe(1);
    expect(activateCard(mismatch, 2)).toBe(mismatch);
    expect(activateCard(initial, -1)).toBe(initial);
    expect(activateCard(initial, 16)).toBe(initial);
  });

  it('starts the clock on the first valid reveal and keeps fractional time', () => {
    const initial = createGame('np1-4-1');
    if (initial === null) throw new Error('Literal fixture must be valid');
    expect(advanceGame(initial, 100).elapsedMs).toBe(0);
    const started = activateCard(initial, 0);
    expect(advanceGame(advanceGame(started, 0.4), 0.6).elapsedMs).toBe(1);
  });

  it('keeps a miss visible for exactly 800ms, then permits another reveal', () => {
    const game = createGame('np1-4-1');
    if (game === null) throw new Error('Literal fixture must be valid');
    const mismatch = activateCard(activateCard(game, 0), 1);
    const beforeClose = advanceGame(mismatch, 799);
    expect(beforeClose.selection.kind).toBe('mismatch');
    expect(activateCard(beforeClose, 2)).toBe(beforeClose);
    const closed = advanceGame(beforeClose, 1);
    expect(closed.selection.kind).toBe('closed');
    expect(activateCard(closed, 2).selection).toEqual({ kind: 'one', index: 2 });
    expect(closed.elapsedMs).toBe(800);
  });

  it('matches immediately and derives victory from all pairs', () => {
    let game = createGame('np1-4-1');
    if (game === null) throw new Error('Literal fixture must be valid');
    for (let face = 0; face < game.deck.length / 2; face += 1) {
      const first = game.deck.indexOf(face);
      const second = game.deck.lastIndexOf(face);
      game = activateCard(activateCard(game, first), second);
    }
    expect(isWon(game)).toBe(true);
    expect(matchedPairCount(game)).toBe(8);
    expect(game.moves).toBe(8);
    expect(game.selection.kind).toBe('closed');
    expect(advanceGame(game, 1000)).toBe(game);
  });

  it('formats elapsed time with unbounded minutes and floored seconds', () => {
    expect(formatTime(3_600_999)).toBe('60:00');
    expect(formatTime(125_999)).toBe('2:05');
  });
});
import { describe, expect, it } from 'vitest';
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts';
import { createGame, isWon, type GameState } from './state.ts';

function validSnapshot(): Record<string, unknown> {
  return {
    version: 1, boardCode: 'np1-4-1', matched: [], selection: { kind: 'closed' },
    moves: 0, elapsedMs: 0, started: false,
  };
}

function decode(value: unknown): ReturnType<typeof decodeSnapshot> {
  return decodeSnapshot(JSON.stringify(value));
}

function restore(value: unknown): GameState {
  const state = decode(value);
  if (state === null) throw new Error('Snapshot fixture must be valid');
  return state;
}

describe('version 1 snapshots', () => {
  it('round trips initial, one-card, mismatch, and completed states', () => {
    const initial = createGame('np1-4-1');
    if (initial === null) throw new Error('Literal fixture must be valid');
    expect(decodeSnapshot(encodeSnapshot(initial))).toMatchObject({ started: false, moves: 0 });
    const one = { ...validSnapshot(), selection: { kind: 'one', index: 0 }, started: true };
    expect(decodeSnapshot(encodeSnapshot(restore(one)))).toMatchObject({ selection: one.selection });
    const mismatch = { ...validSnapshot(), selection: { kind: 'mismatch', first: 0, second: 1, remainingMs: 300 }, moves: 1, started: true };
    expect(decodeSnapshot(encodeSnapshot(restore(mismatch)))).toMatchObject({ selection: mismatch.selection });
    const complete = { ...validSnapshot(), matched: Array.from({ length: 16 }, (_unused, index) => index), moves: 8, started: true };
    const completed = decode(complete);
    expect(completed).not.toBeNull();
    if (completed !== null) expect(isWon(completed)).toBe(true);
  });

  it('rejects malformed JSON, versions, extra keys, and invalid board codes', () => {
    expect(decodeSnapshot('{')).toBeNull();
    expect(decodeSnapshot(' '.repeat(65_537))).toBeNull();
    expect(decode({ ...validSnapshot(), version: 2 })).toBeNull();
    expect(decode({ ...validSnapshot(), extra: true })).toBeNull();
    expect(decode({ ...validSnapshot(), boardCode: 'np1-4-1\n' })).toBeNull();
    expect(decode({ ...validSnapshot(), selection: { kind: 'closed', index: 2 } })).toBeNull();
  });

  it('requires unique whole matched pairs and unmatched in-range selections', () => {
    expect(decode({ ...validSnapshot(), matched: [0] })).toBeNull();
    expect(decode({ ...validSnapshot(), matched: [0, 1], moves: 1, started: true })).toBeNull();
    expect(decode({ ...validSnapshot(), matched: [0, 11, 0], moves: 1, started: true })).toBeNull();
    expect(decode({ ...validSnapshot(), matched: [0, 11], selection: { kind: 'one', index: 0 }, moves: 1, started: true })).toBeNull();
