import { BOARD_SIZES, isBoardSize } from '../board.ts';

const PREFERENCES_KEY = 'neon-pairs:preferences:v1';
const BEST_SCORES_KEY = 'neon-pairs:best-scores:v1';
const MAX_BEST_MOVES = 999_999;

export interface StorageAccess {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export interface GamePreferences {
  readonly size: (typeof BOARD_SIZES)[number];
}

export type BestScores = Readonly<Partial<Record<(typeof BOARD_SIZES)[number], number>>>;

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function readPreferences(storage: StorageAccess | null): GamePreferences | null {
  if (storage === null) return null;
  try {
    const raw = storage.getItem(PREFERENCES_KEY);
    if (raw === null) return null;
    const value: unknown = JSON.parse(raw);
    if (!record(value) || value.version !== 1 || !isBoardSize(value.size)) return null;
    if (Object.keys(value).length !== 2) return null;
    return Object.freeze({ size: value.size });
  } catch {
    return null;
  }
}

export function writePreferences(storage: StorageAccess | null, size: number): void {
  if (storage === null || !isBoardSize(size)) return;
  try {
    storage.setItem(PREFERENCES_KEY, JSON.stringify({ version: 1, size }));
  } catch {
    // Storage is optional; the current session remains playable.
  }
}

export function readBestScores(storage: StorageAccess | null): BestScores {
  if (storage === null) return Object.freeze({});
  try {
    const raw = storage.getItem(BEST_SCORES_KEY);
    if (raw === null) return Object.freeze({});
    const value: unknown = JSON.parse(raw);
    if (!record(value) || value.version !== 1 || !record(value.scores)) return Object.freeze({});
    const scores: Partial<Record<(typeof BOARD_SIZES)[number], number>> = {};
    for (const size of BOARD_SIZES) {
      const score = value.scores[String(size)];
      if (typeof score === 'number' && Number.isSafeInteger(score) && score >= 0 && score <= MAX_BEST_MOVES) {
        scores[size] = score;
      }
    }
    return Object.freeze(scores);
  } catch {
    return Object.freeze({});
  }
}

export function writeBestScores(storage: StorageAccess | null, scores: BestScores): void {
  if (storage === null) return;
  const safeScores: Partial<Record<(typeof BOARD_SIZES)[number], number>> = {};
  for (const size of BOARD_SIZES) {
    const score = scores[size];
    if (typeof score === 'number' && Number.isSafeInteger(score) && score >= 0 && score <= MAX_BEST_MOVES) {
      safeScores[size] = score;
    }
  }
  try {
    storage.setItem(BEST_SCORES_KEY, JSON.stringify({ version: 1, scores: safeScores }));
  } catch {
    // Storage is optional; the current session remains playable.
  }
}

import { BOARD_SIZES, MAX_SEED, isBoardSize } from '../board.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, advanceGame } from '../transitions.ts';
import { createGame, formatTime, GAME_LIMITS, isWon, matchedPairCount, type GameState } from '../state.ts';
import { readBestScores, readPreferences, writeBestScores, writePreferences, type BestScores, type StorageAccess } from './storage.ts';

export interface SessionAnnouncement {
  readonly serial: number;
  readonly text: string;
}

export interface SessionView {
  readonly game: GameState;
  readonly dealId: number;
  readonly paused: boolean;
  readonly best: number | null;
  readonly celebrating: boolean;
  readonly status: string;
  readonly announcement: SessionAnnouncement;
}

export interface SessionEnvironment {
  now(): number;
  setInterval(callback: () => void, milliseconds: number): () => void;
  setTimeout(callback: () => void, milliseconds: number): () => void;
  isVisible(): boolean;
  onVisibilityChange(callback: () => void): () => void;
  readonly storage: StorageAccess | null;
  randomSeed(): number;
}

function initialSeed(environment: SessionEnvironment): number {
  const candidate = environment.randomSeed();
  return Number.isSafeInteger(candidate) && candidate >= 1 && candidate <= MAX_SEED ? candidate : 1;
}

export function makeBrowserEnvironment(): SessionEnvironment {
  const storage = (() => {
    try { return globalThis.localStorage; } catch { return null; }
  })();
  return {
    now: () => performance.now(),
    setInterval: (callback, milliseconds) => {
      const id = globalThis.setInterval(callback, milliseconds);
      return () => globalThis.clearInterval(id);
    },
    setTimeout: (callback, milliseconds) => {
      const id = globalThis.setTimeout(callback, milliseconds);
      return () => globalThis.clearTimeout(id);
    },
    isVisible: () => typeof document === 'undefined' || document.visibilityState !== 'hidden',
    onVisibilityChange: (callback) => {
      if (typeof document === 'undefined') return () => undefined;
      document.addEventListener('visibilitychange', callback);
      return () => document.removeEventListener('visibilitychange', callback);
    },
    storage,
    randomSeed: () => {
      try {
        const values = new Uint32Array(1);
        globalThis.crypto.getRandomValues(values);
        const value = values[0];
        if (value !== undefined) return (value % MAX_SEED) + 1;
      } catch {
        // An unpredictable fresh seed is best effort; play remains available.
      }
      return Math.floor(Math.random() * MAX_SEED) + 1;
    },
  };
}

function codeFor(size: number, seed: number): string {
  return `np1-${size}-${seed}`;
}

export class SessionController {
  private game: GameState;
  private dealId = 0;
  private paused = false;
  private celebrating = false;
  private status = '';
  private announcement: SessionAnnouncement = Object.freeze({ serial: 0, text: '' });
  private scores: BestScores;
  private listeners = new Set<() => void>();
  private view: SessionView;
  private running = false;
  private visible: boolean;
  private lastAt: number;
  private clearInterval: (() => void) | null = null;
  private clearCelebrationTimeout: (() => void) | null = null;
  private removeVisibilityListener: (() => void) | null = null;
  private timerGeneration = 0;

  private readonly environment: SessionEnvironment;

  constructor(environment: SessionEnvironment) {
    this.environment = environment;
    const size = readPreferences(environment.storage)?.size ?? BOARD_SIZES[0];
    const first = createGame(codeFor(size, initialSeed(environment)));
    if (first === null) throw new Error('Initial supported board could not be created');
    this.game = first;
    this.scores = readBestScores(environment.storage);
    this.visible = environment.isVisible();
    this.lastAt = environment.now();
    this.view = this.createView();
  }

  private createView(): SessionView {
    return Object.freeze({
      game: this.game,
      dealId: this.dealId,
      paused: this.paused,
      best: this.scores[this.game.board.size] ?? null,
      celebrating: this.celebrating,
      status: this.status,
      announcement: this.announcement,
    });
  }

  private publish(): void {
    this.view = this.createView();
    for (const listener of this.listeners) listener();
  }

  readonly subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  readonly getSnapshot = (): SessionView => this.view;

  start(): void {
    if (this.running) return;
    this.running = true;
    this.visible = this.environment.isVisible();
    this.lastAt = this.environment.now();
    this.removeVisibilityListener = this.environment.onVisibilityChange(() => this.visibilityChanged());
    this.clearInterval = this.environment.setInterval(() => this.pulse(), 100);
  }

  stop(): void {
    this.running = false;
    this.timerGeneration += 1;
    this.clearInterval?.();
    this.clearInterval = null;
    this.removeVisibilityListener?.();
    this.removeVisibilityListener = null;
    this.clearCelebrationTimeout?.();
    this.clearCelebrationTimeout = null;
  }

  private syncClock(now: number): void {
    const delta = Math.max(0, now - this.lastAt);
    this.lastAt = now;
    if (!this.running || !this.visible || this.paused || !this.game.started || isWon(this.game) || delta === 0) return;
    const previous = this.game;
    const next = advanceGame(previous, delta);
    if (next.elapsedMs !== previous.elapsedMs || next.selection !== previous.selection) {
      this.game = next;
      this.publish();
    }
  }

  private pulse(): void {
    if (!this.visible) return;
    this.syncClock(this.environment.now());
  }

  private visibilityChanged(): void {
    const wasVisible = this.visible;
    const isVisible = this.environment.isVisible();
    if (wasVisible === isVisible) return;
    if (wasVisible) this.syncClock(this.environment.now());
    this.visible = isVisible;
    this.lastAt = this.environment.now();
  }

  private clearCelebration(): void {
    this.clearCelebrationTimeout?.();
    this.clearCelebrationTimeout = null;
    this.celebrating = false;
  }

  private beginDeal(game: GameState, paused: boolean, status = ''): void {
    this.timerGeneration += 1;
    this.clearCelebration();
    this.game = game;
    this.dealId += 1;
    this.paused = paused;
    this.status = status;
    this.lastAt = this.environment.now();
    this.publish();
  }

  private announce(text: string, status: string): void {
    this.status = status;
    this.announcement = Object.freeze({ serial: this.announcement.serial + 1, text });
    this.publish();
  }

  private nextSeed(): number {
    const seed = initialSeed(this.environment);
    return seed === this.game.board.seed ? (seed % MAX_SEED) + 1 : seed;
  }

  readonly activateCard = (index: number): void => {
    if (this.paused) return;
    const now = this.environment.now();
    this.syncClock(now);
    const before = this.game;
    const after = activateCard(before, index);
    if (after === before) return;
    this.game = after;
    if (before.selection.kind === 'one') this.recordTurn(before, after);
    if (!before.started && after.started) this.lastAt = now;
    this.publish();
  };

  private recordTurn(before: GameState, after: GameState): void {
    if (after.matched.length > before.matched.length) {
      const won = isWon(after);
      const text = won
        ? `Pair found. All pairs found in ${after.moves} moves and ${formatTime(after.elapsedMs)}.`
        : `Pair found. ${matchedPairCount(after)} ${matchedPairCount(after) === 1 ? 'pair' : 'pairs'} matched.`;
      this.announce(text, '');
      if (won) this.finishPlayedGame(after);
    } else if (after.selection.kind === 'mismatch') {
      this.announce('No match. Cards close after a short pause.', '');
    }
  }

  private finishPlayedGame(game: GameState): void {
    const previousBest = this.scores[game.board.size];
    if (previousBest === undefined || game.moves < previousBest) {
      this.scores = Object.freeze({ ...this.scores, [game.board.size]: game.moves });
      writeBestScores(this.environment.storage, this.scores);
    }
    this.celebrating = true;
    const generation = this.timerGeneration;
    this.clearCelebrationTimeout = this.environment.setTimeout(() => {
      if (generation !== this.timerGeneration) return;
      this.clearCelebrationTimeout = null;
      this.celebrating = false;
      this.publish();
    }, 600);
  }

  readonly newGame = (): void => {
    const game = createGame(codeFor(this.game.board.size, this.nextSeed()));
    if (game !== null) this.beginDeal(game, false);
  };

  readonly restart = (): void => {
    const game = createGame(this.game.board.boardCode);
    if (game !== null) this.beginDeal(game, false);
  };

  readonly changeSize = (size: number): void => {
    if (!isBoardSize(size) || size === this.game.board.size) return;
    const game = createGame(codeFor(size, this.nextSeed()));
    if (game === null) return;
    writePreferences(this.environment.storage, size);
    this.beginDeal(game, false);
  };

  readonly loadBoard = (draft: string): boolean => {
    const game = createGame(draft.trim());
    if (game === null) {
      this.announce('Invalid board code.', 'Invalid board code.');
      return false;
    }
    writePreferences(this.environment.storage, game.board.size);
    this.announcement = Object.freeze({ serial: this.announcement.serial + 1, text: 'Loaded board.' });
    this.beginDeal(game, false, 'Loaded board.');
    return true;
  };

  readonly loadSnapshot = (draft: string): boolean => {
    const game = decodeSnapshot(draft);
    if (game === null) {
      this.announce('Invalid snapshot.', 'Invalid snapshot.');
      return false;
    }
    const completed = isWon(game);
    const status = completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.';
    writePreferences(this.environment.storage, game.board.size);
    this.announcement = Object.freeze({ serial: this.announcement.serial + 1, text: status });
    this.beginDeal(game, !completed, status);
    return true;
  };

  readonly exportSnapshot = (): string => {
    this.syncClock(this.environment.now());
    return encodeSnapshot(this.game);
  };

  readonly resume = (): void => {
    if (!this.paused) return;
    this.paused = false;
    this.lastAt = this.environment.now();
    this.publish();
  };
}

import { advanceGame, type GameState } from '../transitions.ts';
import type { SessionEnvironment } from './environment.ts';

export class ActiveClock {
  private running = false;
  private visible = true;
  private lastAt = 0;
  private loopGeneration = 0;
  private deadlineGeneration = 0;
  private clearPulse: (() => void) | null = null;
  private clearDeadline: (() => void) | null = null;
  private removeVisibility: (() => void) | null = null;
  private readonly environment: SessionEnvironment;
  private readonly readGame: () => GameState;
  private readonly readDealId: () => number;
  private readonly readPaused: () => boolean;
  private readonly writeGame: (game: GameState) => void;

  constructor(
    environment: SessionEnvironment,
    readGame: () => GameState,
    readDealId: () => number,
    readPaused: () => boolean,
    writeGame: (game: GameState) => void,
  ) {
    this.environment = environment;
    this.readGame = readGame;
    this.readDealId = readDealId;
    this.readPaused = readPaused;
    this.writeGame = writeGame;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.visible = this.environment.isVisible();
    this.lastAt = this.environment.now();
    this.removeVisibility = this.environment.onVisibilityChange(() => this.visibilityChanged());
    this.installPulse();
    this.scheduleDeadline();
  }

  stop(): void {
    this.running = false;
    this.loopGeneration += 1;
    this.deadlineGeneration += 1;
    this.clearPulse?.();
    this.clearPulse = null;
    this.clearDeadline?.();
    this.clearDeadline = null;
    this.removeVisibility?.();
    this.removeVisibility = null;
  }

  syncNow(): void {
    this.syncAt(this.environment.now());
  }

  gameChanged(): void {
    this.lastAt = this.environment.now();
    this.scheduleDeadline();
  }

  dealChanged(): void {
    this.lastAt = this.environment.now();
    this.cancelDeadline();
    this.installPulse();
    this.scheduleDeadline();
  }

  pauseChanged(): void {
    this.lastAt = this.environment.now();
    this.scheduleDeadline();
  }

  private installPulse(): void {
    this.clearPulse?.();
    this.clearPulse = null;
    this.loopGeneration += 1;
    if (!this.running) return;
    const generation = this.loopGeneration;
    this.clearPulse = this.environment.setInterval(() => {
      if (generation !== this.loopGeneration || !this.visible) return;
      this.syncNow();
    }, 100);
  }

  private syncAt(now: number): void {
    const delta = Math.max(0, now - this.lastAt);
    this.lastAt = now;
    if (!this.running || !this.visible || this.readPaused() || delta === 0) return;
    const previous = this.readGame();
    const next = advanceGame(previous, delta);
    if (next.elapsedMs === previous.elapsedMs && next.selection === previous.selection) return;
    this.writeGame(next);
    if (next.selection !== previous.selection) this.scheduleDeadline();
  }

  private visibilityChanged(): void {
    const visible = this.environment.isVisible();
    if (visible === this.visible) return;
    if (this.visible) this.syncAt(this.environment.now());
    this.visible = visible;
    this.lastAt = this.environment.now();
    if (visible) this.scheduleDeadline();
    else this.cancelDeadline();
  }

  private cancelDeadline(): void {
    this.deadlineGeneration += 1;
    this.clearDeadline?.();
    this.clearDeadline = null;
  }

  private scheduleDeadline(): void {
    this.cancelDeadline();
    if (!this.running || !this.visible || this.readPaused()) return;
    const selection = this.readGame().selection;
    if (selection.kind !== 'mismatch') return;
    const generation = this.deadlineGeneration;
    const dealId = this.readDealId();
    this.clearDeadline = this.environment.setTimeout(() => {
      if (generation !== this.deadlineGeneration || dealId !== this.readDealId()) return;
      if (this.readGame().selection !== selection) return;
      this.clearDeadline = null;
      this.syncNow();
      this.scheduleDeadline();
    }, selection.remainingMs);
  }
}

import { BOARD_SIZES } from '../board.ts';
import { activateCard } from '../transitions.ts';
import { createGame, GAME_LIMITS, isWon, type GameState } from '../state.ts';
