import type { JSX, KeyboardEvent, MouseEvent } from 'react';
import { CardBack, FaceArtwork } from './FaceArtwork.tsx';
import type { FaceDescription } from './face.ts';

export interface BoardCardProps {
  readonly index: number;
  readonly size: number;
  readonly face: FaceDescription | null;
  readonly matched: boolean;
  readonly blocked: boolean;
  readonly tabStop: boolean;
  readonly onActivate: (index: number) => void;
  readonly onFocus: (index: number) => void;
  readonly onKeyDown: (event: KeyboardEvent<HTMLButtonElement>, index: number) => void;
  readonly refCallback: (button: HTMLButtonElement | null) => void;
}

function positionName(index: number, size: number): string {
  const row = Math.floor(index / size) + 1;
  const column = (index % size) + 1;
  return 'Row ' + row + ', column ' + column;
}

function activateClick(event: MouseEvent<HTMLButtonElement>, index: number, activate: (index: number) => void): void {
  if (event.button !== 0 || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  activate(index);
}

export function BoardCard({
  index,
  size,
  face,
  matched,
  blocked,
  tabStop,
  onActivate,
  onFocus,
  onKeyDown,
  refCallback,
}: BoardCardProps): JSX.Element {
  const stateName = matched ? 'matched' : face === null ? 'closed' : 'revealed';
  const cardName = positionName(index, size) + (face === null ? ', closed' : ', ' + face.name + ', ' + stateName);
  return (
    <button
      ref={refCallback}
      className={matched ? 'game-card is-matched' : face === null ? 'game-card' : 'game-card is-revealed'}
      type="button"
      aria-label={cardName}
      aria-disabled={matched || blocked}
      tabIndex={tabStop ? 0 : -1}
      onClick={(event) => activateClick(event, index, onActivate)}
      onFocus={(event) => {
        onFocus(index);
        event.currentTarget.scrollIntoView({ block: 'nearest', inline: 'nearest' });
      }}
      onKeyDown={(event) => onKeyDown(event, index)}
      data-card-index={index}
    >
      {face === null ? <CardBack /> : <FaceArtwork id={face.id} />}
      {matched && <span className="matched-check" aria-hidden="true">✓</span>}
    </button>
  );
}
import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type KeyboardEvent } from 'react';
import type { GameState } from '../state.ts';
import { BoardCard } from './BoardCard.tsx';
import { describeFace } from './face.ts';
import { nextBoardFocus } from './focus.ts';
import './board.css';

export interface BoardFocusHandle {
  focusRememberedCard(): void;
}

export interface BoardProps {
  readonly game: GameState;
  readonly dealId: number;
  readonly paused: boolean;
  readonly onActivate: (index: number) => void;
}

export const Board = forwardRef<BoardFocusHandle, BoardProps>(function Board(
  { game, dealId, paused, onActivate },
  ref,
) {
  const size = game.board.size;
  const [tabStop, setTabStop] = useState(0);
  const tabStopRef = useRef(tabStop);
  const buttons = useRef(new Map<number, HTMLButtonElement>());
  const matched = new Set(game.matched);

  useEffect(() => {
    tabStopRef.current = 0;
    setTabStop(0);
  }, [dealId]);


  useImperativeHandle(ref, () => ({
    focusRememberedCard() {
      buttons.current.get(tabStopRef.current)?.focus();
    },
  }), []);

  const rememberFocus = (index: number): void => {
    tabStopRef.current = index;
    setTabStop(index);
  };

  const moveFocus = (event: KeyboardEvent<HTMLButtonElement>, index: number): void => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destination = nextBoardFocus(index, size, event.key);
    if (destination === null) return;
    event.preventDefault();
    buttons.current.get(destination)?.focus();
  };

  const columns = 'repeat(' + size + ', clamp(44px, calc((100cqw - ' + ((size - 1) * 6) + 'px) / ' + size + '), 88px))';
  return (
    <section className="board-section" aria-label={size + ' by ' + size + ' card board'}>
      <p className="board-hint">Use the arrow keys to move. Enter or Space reveals a card.</p>
      <div className="board-scroll">
        <div className="card-grid" style={{ gridTemplateColumns: columns }}>
          {game.deck.map((faceId, index) => {
            const isMatched = matched.has(index);
            let visible = isMatched;
            switch (game.selection.kind) {
              case 'closed':
                break;
              case 'one':
                visible = visible || game.selection.index === index;
                break;
              case 'mismatch':
                visible = visible || game.selection.first === index || game.selection.second === index;
                break;
            }
            const blocked = paused || isMatched || game.selection.kind === 'mismatch';
            return (
              <BoardCard
                key={index}
                index={index}
                size={size}
                face={visible ? describeFace(faceId) : null}
                matched={isMatched}
                blocked={blocked}
                tabStop={tabStop === index}
                onActivate={onActivate}
                onFocus={rememberFocus}
                onKeyDown={moveFocus}
                refCallback={(button) => {
                  if (button === null) buttons.current.delete(index);
                  else buttons.current.set(index, button);
                }}
              />
            );
          })}
        </div>
      </div>
    </section>
  );
});
